CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL);
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations(id),email text NOT NULL,password_hash text NOT NULL,role text NOT NULL CHECK(role IN ('rep','manager','marketing','support','admin')),UNIQUE(org_id,email));
CREATE TABLE IF NOT EXISTS companies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,website text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,email text,phone text,owner_id uuid REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS contact_email_unique ON contacts(org_id,lower(email)) WHERE email IS NOT NULL;
CREATE TABLE IF NOT EXISTS contact_companies(contact_id uuid REFERENCES contacts(id) ON DELETE CASCADE,company_id uuid REFERENCES companies(id) ON DELETE CASCADE,PRIMARY KEY(contact_id,company_id));
CREATE TABLE IF NOT EXISTS leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,email text,status text NOT NULL DEFAULT 'new',score integer DEFAULT 0,owner_id uuid REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS pipelines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL);
CREATE TABLE IF NOT EXISTS stages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),pipeline_id uuid NOT NULL REFERENCES pipelines(id),name text NOT NULL,position integer NOT NULL,probability numeric(4,3) NOT NULL DEFAULT 0 CHECK(probability BETWEEN 0 AND 1));
CREATE TABLE IF NOT EXISTS opportunities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,company_id uuid REFERENCES companies(id),stage_id uuid REFERENCES stages(id),owner_id uuid REFERENCES users(id),amount numeric(14,2) NOT NULL DEFAULT 0,close_date date,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS opportunity_members(opportunity_id uuid REFERENCES opportunities(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(opportunity_id,user_id));
CREATE TABLE IF NOT EXISTS activities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations(id),type text NOT NULL,summary text NOT NULL,lead_id uuid REFERENCES leads(id),opportunity_id uuid REFERENCES opportunities(id),owner_id uuid REFERENCES users(id),due_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS automation_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,event text NOT NULL,action text NOT NULL,enabled boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS automation_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),rule_id uuid NOT NULL REFERENCES automation_rules(id),event_key text NOT NULL,status text NOT NULL,created_at timestamptz DEFAULT now(),UNIQUE(rule_id,event_key));
CREATE TABLE IF NOT EXISTS audit_log(id bigserial PRIMARY KEY,org_id uuid NOT NULL,actor_id uuid,entity text NOT NULL,entity_id uuid,action text NOT NULL,created_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS leads_org_status ON leads(org_id,status);CREATE INDEX IF NOT EXISTS opportunities_org_stage ON opportunities(org_id,stage_id);
